        return try await perform(input)
    }
}

public struct ShareMissionIntent: AppIntent {
    public static let title: LocalizedStringResource = "Share mission"
    public static let description = IntentDescription("Prepare a mission to send to another agent, within your consent.")

    @Parameter(title: "Mission", description: "the local mission to share (its local uuid id)")
    public var missionId: String
    @Parameter(title: "To agent", description: "the recipient agent's join-key agentId")
    public var toAgentId: String
    @Parameter(title: "Scope", description: "what to share: 'mission' (title/status + shareable learnings) or 'outcomes' (the result rows); both require an explicit grant under the tiered policy")
    public var scope: ShareMissionScopeValue
    @Parameter(title: "Proof", description: "optional opaque proof to stamp on the envelope (for a non-TOFU recipient verifier)")
    public var proof: String?

    public init() {}

    public init(_ input: ShareMissionInput) {
        self.init()
        self.missionId = input.missionId
        self.toAgentId = input.toAgentId
        self.scope = input.scope
        self.proof = input.proof
    }

    public var input: ShareMissionInput {
        ShareMissionInput(missionId: missionId, toAgentId: toAgentId, scope: scope, proof: proof)
    }

    @MainActor
    public func perform() async throws -> some IntentResult & ProvidesDialog {
        // Consequential: the person says yes before it acts.
        if let confirm = ShareMissionAction.confirm { try await confirm(self.input) } else { try await requestConfirmation(result: .result(dialog: IntentDialog(ShareMissionAction.confirmation))) }
        let input = self.input
        let result: Result<ShareMissionOutput, any Error>
        do { result = .success(try await ShareMissionAction.run(input)) } catch { result = .failure(error) }
        if let dialog = ShareMissionAction.dialog { return .result(dialog: try await dialog(input, result)) }
        _ = try result.get()
        return .result(dialog: "Done.")
    }
}

